def semver_sort(versions):
    def parse_version(v):
        # Split by '+' to remove build metadata
        v_without_build = v.split('+')[0]

        # Split by '-' to separate core version and pre-release
        if '-' in v_without_build:
            core, prerelease = v_without_build.split('-', 1)
        else:
            core = v_without_build
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                # Check if identifier is all digits
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))  # 0 means numeric
                else:
                    prerelease_identifiers.append((1, identifier))  # 1 means string

        return (major, minor, patch, prerelease_identifiers)

    def compare_key(item):
        index, version = item
        major, minor, patch, prerelease_identifiers = parse_version(version)

        # Create sort key:
        # - (major, minor, patch) for numeric comparison
        # - Empty list for no pre-release (sorts after pre-release)
        # - Non-empty list for pre-release (sorts before no pre-release)
        # - index for stable sort

        if not prerelease_identifiers:
            # No pre-release: sorts after any pre-release version
            return (major, minor, patch, (1,), index)
        else:
            # Has pre-release: sorts before any non-pre-release version
            return (major, minor, patch, (0, tuple(prerelease_identifiers)), index)

    # Create list of (index, version) to maintain input order for equal precedence
    indexed_versions = list(enumerate(versions))

    # Sort by the comparison key
    sorted_indexed = sorted(indexed_versions, key=compare_key)

    # Extract sorted versions
    return [version for _, version in sorted_indexed]

